    for (const k of v.mode === 'bef' ? ['D', 'BEF'] : ['BCEF']) if (!(num(v[k]) > 0)) p.push(T('p.vnum', { what: T('v.' + k) }));
    if (!(num(v.R) >= 0)) p.push(T('p.vnum', { what: T('v.R') }));
    const cf = num(v.CF); if (!(cf > 0 && cf <= 1)) p.push(T('p.cf', { c: 'CF' }));
